// These protocol descriptors are generated by original firmware 1.11.0 for
// each product identity. They contain no executable firmware or private data.
func originalModelDescriptors(t *testing.T) map[uint16][]byte {
	t.Helper()
	fixtures := map[uint16]string{
		0x0e37: "12010002000000080e0b370e110101020301090211010401008032090400000001010000" +
			"0a2401000169000201020c24020a01020002030000060c24020401020001040000040924" +
			"060504010300040924030601010005040c24020101010002030000050a24060208010300" +
			"0005092406070a010300060d240408020107020300000005092403030103000205090401" +
			"000001020000090401010101020000072401060101001424020101021004401f00803e00" +
			"44ac0080bb000905820d6200010000072501010101000904020000010200000904020101" +
			"01020000072401010101001724020102021005401f00803e00007d0044ac0080bb000905" +
			"020dc40001000007250101010100090403000103000000092111010001225a0107058103" +
			"400001",
		0x0e36: "12010002000000080e0b360e110101020301090211010401008032090400000001010000" +
			"0a2401000169000201020c24020a01020002030000060c24020402040301040000040924" +
			"060504010300040924030601010005040c24020101010002030000050a24060208010300" +
			"0005092406070a010300060d240408020107020300000005092403030204040205090401" +
			"000001020000090401010101020000072401060101001424020101021004401f00803e00" +
			"44ac0080bb000905820d6200010000072501010101000904020000010200000904020101" +
			"01020000072401010101001724020102021005401f00803e00007d0044ac0080bb000905" +
			"020dc4000100000725010101010009040300010300000009211101000122860107058103" +
			"400001",
		0x0e39: "12010002000000080e0b390e110101020301090210010401008032090400000001010000" +
			"0a2401000168000201020c24020a01020002030000060c24020401020001040000040924" +
			"060504010300040924030601010005040c24020101010001010000050924060208010300" +
			"05092406070a010300060d24040802010701010000000509240303010300020509040100" +
			"0001020000090401010101020000072401060101001424020101021004401f00803e0044" +
			"ac0080bb000905820d620001000007250101010100090402000001020000090402010101" +
			"020000072401010101001724020101021005401f00803e00007d0044ac0080bb00090502" +
			"0d620001000007250101010100090403000103000000092111010001225a010705810340" +
			"0001",
		0x0e38: "12010002000000080e0b380e110101020301090210010401008032090400000001010000" +
			"0a2401000168000201020c24020a01020002030000060c24020402040301040000040924" +
			"060504010300040924030601010005040c24020101010001010000050924060208010300" +
			"05092406070a010300060d24040802010701010000000509240303020404020509040100" +
			"0001020000090401010101020000072401060101001424020101021004401f00803e0044" +
			"ac0080bb000905820d620001000007250101010100090402000001020000090402010101" +
			"020000072401010101001724020101021005401f00803e00007d0044ac0080bb00090502" +
			"0d6200010000072501010101000904030001030000000921110100012286010705810340" +
			"0001",
	}
	result := make(map[uint16][]byte)
	for pid, encoded := range fixtures {
		data, err := hex.DecodeString(encoded)
		if err != nil {
			t.Fatal(err)
		}
		result[pid] = data
	}
	return result
}

func TestVolumeProfilesBindModelFirmwareAndConnection(t *testing.T) {
	for pid, data := range originalModelDescriptors(t) {
		profile, ok := profileForPID(pid)
		info, err := Inspect(data)
		if !ok || err != nil || info.Channels != profile.channels {
			t.Fatal(pid, info, err)
		}
		c := ForDevice(pid, Firmware, "usb")
		if c.Read != "saved" || !c.SetPercent || c.Reason != "" {
			t.Fatal(c)
		}
		for _, connection := range []string{"dongle", "bluetooth", ""} {
			c = ForDevice(pid, Firmware, connection)
			if c.Read != "unavailable" || c.SetPercent || c.Reason == "" {
				t.Fatal("USB profile escaped to another connection", c)
			}
		}
		c = ForDevice(pid, "1.12.0", "usb")
		if c.Read != "unavailable" || c.SetPercent {
			t.Fatal("unknown firmware accepted", c)
		}
		// A matching device ID cannot authorize a different model's audio layout.
		for other, otherData := range originalModelDescriptors(t) {
			if other == pid {
				continue
			}
			changed := append([]byte(nil), otherData...)
			changed[10], changed[11] = byte(pid), byte(pid>>8)
			if _, err := Inspect(changed); err == nil {
				t.Fatal("cross-model layout accepted", pid, other)
			}
		}
	}
	for _, pid := range []uint16{0, 0x0e35, 0x24c7, 0x253d, 0xffff} {
		c := ForDevice(pid, Firmware, "usb")
		if c.SetPercent || c.Read != "unavailable" {
			t.Fatal("unverified model enabled", pid, c)
		}
	}
}

func TestSavedVolumeReadNeverWrites(t *testing.T) {
	p := &peer{code: -12288}
	value, err := ReadSaved(context.Background(), p)
	if err != nil || value.Source != "saved" || value.Percent != 0 || len(p.requests) != 1 || p.requests[0].kind != 0xa2 {
		t.Fatal(value, err, p.requests)
	}
	p = &peer{short: true}
	if _, err := ReadSaved(context.Background(), p); err == nil || len(p.requests) != 1 {
		t.Fatal("invalid saved read accepted", err)
	}
}
